import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_storage/firebase_storage.dart';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';
class EditListingScreen extends StatefulWidget{final String id;final Map<String,dynamic> data;const EditListingScreen({super.key,required this.id,required this.data});@override State<EditListingScreen> createState()=>_E();}
class _E extends State<EditListingScreen>{late final TextEditingController title,description,price;late String status;late List<String> urls;bool saving=false;@override void initState(){super.initState();title=TextEditingController(text:widget.data['title']??'');description=TextEditingController(text:widget.data['description']??'');price=TextEditingController(text:(widget.data['price']??0).toString());status=widget.data['status']??'active';urls=List<String>.from(widget.data['imageUrls']??[]);}
Future<void> addPhoto()async{final xs=await ImagePicker().pickMultiImage(imageQuality:85);for(final x in xs){final r=FirebaseStorage.instance.ref('products/edit/'+widget.id+'/'+DateTime.now().microsecondsSinceEpoch.toString()+'.jpg');await r.putFile(File(x.path));urls.add(await r.getDownloadURL());}setState((){});}
Future<void> save()async{setState(()=>saving=true);try{await FirebaseFirestore.instance.collection('products').doc(widget.id).update({'title':title.text.trim(),'description':description.text.trim(),'price':int.tryParse(price.text)??0,'imageUrls':urls,'imageUrl':urls.isEmpty?'':urls.first,'status':status,'updatedAt':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}finally{if(mounted)setState(()=>saving=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Edit Iklan')),body:ListView(padding:const EdgeInsets.all(20),children:[Wrap(spacing:8,children:[...urls.map((u)=>Stack(children:[Image.network(u,width:90,height:90,fit:BoxFit.cover),Positioned(right:0,child:IconButton(onPressed:()=>setState(()=>urls.remove(u)),icon:const CircleAvatar(radius:12,child:Icon(Icons.close,size:14))))])),OutlinedButton.icon(onPressed:addPhoto,icon:const Icon(Icons.add_a_photo),label:const Text('Tambah Foto'))]),TextField(controller:title,decoration:const InputDecoration(labelText:'Judul')),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Harga')),TextField(controller:description,maxLines:5,decoration:const InputDecoration(labelText:'Deskripsi')),DropdownButtonFormField(value:status,items:const [DropdownMenuItem(value:'active',child:Text('Aktif')),DropdownMenuItem(value:'sold',child:Text('Terjual')),DropdownMenuItem(value:'inactive',child:Text('Nonaktif'))],onChanged:(v)=>setState(()=>status=v!)),const SizedBox(height:20),FilledButton(onPressed:saving?null:save,child:Text(saving?'Menyimpan...':'Simpan Perubahan'))]));}